style.css:
@-moz-document url-prefix("https://torbox.app") {
/* ===== VARIABLES ===== */
  * {
    /* Backgrounds */
    --color-bg: #2d1810;
    /* main background - dark brown */
    --color-bg-alt: #3d2317;
    /* secondary background - warmer brown */
    --color-surface: #342218;
    /* panels, cards, etc. */
    /* Text */
    --color-text: #f4e4c7;
    /* main text - warm cream */
    --color-text-sub: #fff3d4;
    /* lighter text, subtitles */
    --color-text-muted: #c7a876;
    /* muted/secondary text - muted gold */
    /* Accent & Interactive */
    --color-accent: #ffb347;
    /* caret, highlights - warm orange */
    --color-accent-hover: #ffc77a;
    /* hover states - lighter orange */
    --color-accent-dark: #e67e22;
    /* darker accent variant */
    /* Status Colors */
    --color-success: #27ae60;
    /* green for active/ready states */
    --color-success-bg: #1e8449;
    /* darker green for backgrounds */
    --color-warning: #f39c12;
    /* orange/yellow for warnings */
    --color-warning-bg: #d68910;
    /* darker orange */
    --color-error: #e74c3c;
    /* red for errors */
    --color-error-dark: #c0392b;
    /* darker red */
    /* UI Elements */
    --color-border: #5d3a24;
    /* borders, dividers - warm brown */
    --color-border-light: #7a4d32;
    /* lighter borders */
    --color-input: #3d2817;
    /* input fields */
    --color-input-focus: #4a3020;
    /* focused inputs */
    /* Special Elements */
    --color-badge: #e67e22;
    /* badges, tags - burnt orange */
    --color-badge-private: #8e44ad;
    /* private torrents - purple */
    --color-cached: #f39c12;
    /* cached downloads - amber */
    --color-progress: #2ecc71;
    /* progress bars */
    --color-graph: #d35400;
    /* charts/graphs - dark orange */
  }

  /* ===== ROOT STYLING ===== */
  #root {
    background: var(--color-bg) !important;
    color: var(--color-text) !important;
  }

  /* ===== ICONS ===== */
  .fill-white,
  .text-white {
    fill: var(--color-accent) !important;
    color: var(--color-accent) !important;
  }

  /* ===== POP-UPS ===== */
  [id^="headlessui-menu-items"] {
    background-color: var(--color-bg-alt) !important;
  }

  [id^="headlessui-popover-panel"] {
    background-color: var(--color-bg) !important;
  }

  [id^="headlessui-popover-panel"] div button {
    border-color: var(--color-accent-dark) !important;
  }


  /* ===== LAYOUT CONTAINERS ===== */
  .sidebar,
  .downloads {
    background-color: var(--color-bg-alt) !important;
  }

  .downloads .sticky {
    background-color: var(--color-bg-alt) !important;
    border-bottom: 1px solid var(--color-border) !important;
  }

  /* ===== HEADER STATISTICS ===== */
  .downloads .sticky .flex > div:last-child span {
    color: var(--color-error-dark) !important;
    /* inactive downloads */
  }

  .downloads .sticky .flex > div:first-child span {
    color: var(--color-success) !important;
    /* active downloads */
  }

  .downloads .sticky .flex > div:nth-child(2) span {
    color: var(--color-accent) !important;
    /* total downloads */
  }

  /* ===== DOWNLOAD CARDS ===== */
  [id^="headlessui-popover-button"] {
    background-color: var(--color-surface) !important;
    border: 1px solid var(--color-border) !important;
  }

  /* ===== STATUS BADGES ===== */
  .flex.flex-wrap.gap-3.items-center p.bg-gray-500 {
    background-color: var(--color-badge) !important;
    /* torrent */
  }

  .flex.flex-wrap.gap-3.items-center p.bg-indigo-500 {
    background-color: var(--color-badge-private) !important;
    /* private */
  }

  .flex.flex-wrap.gap-3.items-center p.bg-\[\#04BF8A\] {
    background-color: var(--color-success) !important;
    /* download ready */
  }

  .flex.flex-wrap.gap-3.items-center p.bg-blue-500 {
    background-color: var(--color-cached) !important;
    /* cached */
  }

  /* ===== ADD BUTTONS ===== */
  .downloads button.rounded-md.font-bold {
    background: none !important;
    background-color: var(--color-success-bg) !important;
  }

  .downloads button.rounded-md.font-bold:hover {
    background-color: var(--color-success) !important;
  }

  /* ===== PLAN EXPIRATION ===== */
  /* Get More Time button */
  a.rounded-md.p-2.w-full.bg-red-500 {
    background-color: var(--color-error) !important;
  }

  a.rounded-md.p-2.w-full.bg-red-500:hover {
    background-color: var(--color-error-dark) !important;
  }

  /* Hide explore addons button */
  a.rounded-md.p-2.w-full.bg-\[\#F59E0B\] {
    background-color: var(--color-warning-bg) !important;
  }

  a.rounded-md.p-2.w-full.bg-\[\#F59E0B\]:hover {
    background-color: var(--color-warning) !important;
  }

  /* ===== FOOTER ===== */
  footer {
    background-color: var(--color-bg) !important;
  }

  /* ===== FORM STYLING ===== */
  form.bg-\[\#0f1117\] > div {
    background-color: var(--color-bg-alt) !important;
  }

  textarea, input {
    background-color: var(--color-input) !important;
    border: 1px solid var(--color-border) !important;
    color: var(--color-text) !important;
  }

  textarea:focus, input:focus {
    background-color: var(--color-input-focus) !important;
    border-color: var(--color-accent) !important;
    outline: none !important;
  }

  button.relative.block.w-full {
    background-color: var(--color-success-bg) !important;
    color: var(--color-text) !important;
    border: 1px solid var(--color-border) !important;
  }

  button.relative.block.w-full:hover {
    background-color: var(--color-success) !important;
    border-color: var(--color-accent) !important;
  }

  /* ===== CARD STYLING ===== */
  .aspect-square.border.rounded-md.border-\[\#212A36\].text-center.bg-\[\#1E2129\] {
    background-color: var(--color-surface) !important;
    border-color: var(--color-border) !important;
    color: var(--color-text) !important;
  }

  .aspect-square.border.rounded-md.border-\[\#212A36\].text-center.bg-\[\#1E2129\]:hover {
    border-color: var(--color-success) !important;
    background-color: var(--color-bg-alt) !important;
  }

  /* ===== SETTINGS PAGE ===== */
  .w-full.h-full.border.p-4.rounded-md.border-\[\#212A36\].bg-\[\#1E2129\].max-w-7xl.mb-4 {
    background-color: var(--color-surface) !important;
    border-color: var(--color-border) !important;
    color: var(--color-text) !important;
  }

  /* ===== FIXES ===== */
  /* Fix API key not being blurred */
  div.relative input.text-xs.px-3 {
    color: transparent !important;
  }
}
